// This code checks if the applicant selected the withdrawal option
// in either of two specific questions from the Fillout form

// Get the questions object from the form submission
const questions = $('Fillout Trigger').first().json.questions;

// Check question v4TV: "Before we move forward, please confirm..."
const programStructureAnswer = questions?.['v4TV']?.value;
console.log('programStructureAnswer', programStructureAnswer);

// Check question 7civ: "Would you like to proceed?"
const proceedAnswer = questions?.['7civ']?.value;
console.log('proceedAnswer', proceedAnswer);

// Define the exact withdrawal text we're looking for
const withdrawalText = "This won't be possible for me, please withdraw my application";

// Check if either question has the withdrawal response
const isWithdrawn = 
  programStructureAnswer === withdrawalText || 
  proceedAnswer === withdrawalText;

// Determine which question triggered the withdrawal (if any)
let withdrawalReason = null;
if (isWithdrawn) {
  if (programStructureAnswer === withdrawalText) {
    withdrawalReason = 'Program Structure Question (v4TV)';
  } else if (proceedAnswer === withdrawalText) {
    withdrawalReason = 'Proceed Question (7civ)';
  }
}

// Return the result with the withdrawal flag
return {
  json: {
    //...$input.item.json,
    isWithdrawn: isWithdrawn,
    withdrawalReason: withdrawalReason
  }
};

