// Helper function to find all occurrences
function findAllTextOccurrences(content, searchText) {
  const occurrences = [];

  if (!content || !Array.isArray(content)) {
    return occurrences;
  }

  for (let element of content) {
    if (element.paragraph && element.paragraph.elements) {
      for (let textElement of element.paragraph.elements) {
        if (textElement.textRun && textElement.textRun.content) {
          const text = textElement.textRun.content;
          const startIndex = textElement.startIndex;

          let index = text.indexOf(searchText);
          while (index !== -1) {
            occurrences.push({
              startIndex: startIndex + index,
              endIndex: startIndex + index + searchText.length
            });
            index = text.indexOf(searchText, index + 1);
          }
        }
      }
    }
  }

  return occurrences;
}

