for (let heading of mainHeadings14pt) {
  const occurrences = findAllTextOccurrences(bodyContent, heading);

  for (let range of occurrences) {
    formattingRequests.push({
      updateTextStyle: {
        range: {
          startIndex: range.startIndex,
          endIndex: range.endIndex
        },
        textStyle: {
          bold: true,
          fontSize: {
            magnitude: 14,
            unit: "PT"
          },
          foregroundColor: {
            color: {
              rgbColor: {
                red: 0.984,
                green: 0.027,
                blue: 0.024
              }
            }
          }
        },
        fields: "bold,fontSize,foregroundColor"
      }
    });
  }
}

// Format 13pt headings
for (let heading of mainHeadings13pt) {
  const occurrences = findAllTextOccurrences(bodyContent, heading);

  for (let range of occurrences) {
    formattingRequests.push({
      updateTextStyle: {
        range: {
          startIndex: range.startIndex,
          endIndex: range.endIndex
        },
        textStyle: {
          bold: true,
          fontSize: {
            magnitude: 13,
            unit: "PT"
          },
          foregroundColor: {
            color: {
              rgbColor: {
                red: 0.984,
                green: 0.027,
                blue: 0.024
              }
            }
          }
        },
        fields: "bold,fontSize,foregroundColor"
      }
    });
  }
}

// Format 11pt sub-headings
for (let heading of subHeadings11pt) {
  const occurrences = findAllTextOccurrences(bodyContent, heading);

  for (let range of occurrences) {
    formattingRequests.push({
      updateTextStyle: {
        range: {
          startIndex: range.startIndex,
          endIndex: range.endIndex
        },
        textStyle: {
          bold: true,
          fontSize: {
            magnitude: 11,
            unit: "PT"
          }
        },
        fields: "bold,fontSize"
      }
    });
  }
}

return {
